_elementor_page_settings.custom_css:
.doc-hero{position:relative;background:linear-gradient(115deg,#161b56 0%,#1b216b 60%,#283190 100%);overflow:hidden;padding:clamp(3rem,2rem + 3.5vw,5rem) clamp(1.25rem,.5rem + 3vw,3rem);}
.doc-hero .e-con-inner{max-width:1240px;width:100%;margin:0 auto;}
.doc-hero .elementor-widget-heading,.doc-hero .elementor-widget-text-editor,.doc-hero .elementor-widget-button{position:relative;z-index:1;}
.doc-hero h1.elementor-heading-title{color:#fff;font-size:clamp(2.25rem,1.5rem + 2.6vw,3.25rem);font-weight:800;letter-spacing:-.02em;line-height:1.2;}
.doc-hero .subhead p{color:#b9c0e6;font-size:1.125rem;line-height:1.6;max-width:62ch;margin:0;}
.doc-hero .subhead{margin-top:.75rem;}
.doc-hero .hero-cta{margin-top:1.5rem;}
.doc-hero .hero-motif{position:absolute;right:-8%;top:50%;transform:translateY(-50%);width:min(58vw,760px);pointer-events:none;z-index:0;}
.doc-hero .hero-motif img{width:100%;height:auto;display:block;opacity:.16;}
.hiw-main{max-width:1140px;width:100% !important;margin:0 auto !important;padding:4rem clamp(1.25rem,.5rem + 3vw,3rem) 6rem;gap:0;}
.hiw-h2 h2.elementor-heading-title{color:#1b216b;font-size:clamp(1.5rem,1.1rem + 1.2vw,2rem);font-weight:700;line-height:1.25;}
.hiw-h3 h2.elementor-heading-title{color:#1b216b;font-size:1.35rem;font-weight:700;line-height:1.3;}
.hiw-main ul{margin:0;padding-left:1.2rem;color:#242d28;line-height:1.7;}
.hiw-main ul li{margin-bottom:.5rem;}
.hiw-btn a.elementor-button{background:#3765f8 !important;color:#fff !important;border-radius:8px;font-weight:600;font-size:.9375rem;padding:11px 20px;}
.hiw-btn a.elementor-button:hover{background:#1b216b !important;}
.hiw-btn.footer-nolink a.elementor-button{background:#eceff2 !important;color:#8b938c !important;}
.hiw-cards{display:flex;gap:24px;align-items:stretch;margin-bottom:4.5rem;}
.hiw-card{flex:1;background:#fff;border:1px solid #e3e7ea;border-radius:16px;box-shadow:0 2px 8px rgba(27,33,107,.07);padding:1.5rem;gap:1rem;}
.hiw-cardimg img{width:100%;height:260px;object-fit:cover;border-radius:10px;}
.hiw-btnrow{display:flex;flex-direction:row;gap:12px;}
.hiw-center .elementor-heading-title{text-align:center;}
.hiw-icons{display:flex;flex-direction:row;justify-content:center;gap:clamp(1.5rem,4vw,4rem);margin:2rem 0 4.5rem;}
.hiw-iconbox{align-items:center;gap:.5rem;flex:0 0 auto;}
.hiw-icon img{width:86px;height:86px;object-fit:contain;}
.hiw-iconlabel p{margin:0;color:#1b216b;font-weight:600;font-size:.9375rem;text-align:center;}
.hiw-row{display:flex;flex-direction:row;align-items:center;gap:clamp(2rem,4vw,4rem);margin-bottom:4.5rem;}
.hiw-row > .e-con.hiw-coltext{flex:1 1 0% !important;width:auto !important;min-width:0;gap:1rem;}
.hiw-row > .elementor-widget.hiw-colimg{flex:1 1 0% !important;min-width:0;width:auto !important;}
.hiw-colimg img{width:100%;border-radius:14px;}
.hiw-narrow{max-width:70ch;margin:0 auto 2rem;color:#5d665f;}
.hiw-eyebrow,.hiw-eyebrow-light{font-size:.8125rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;}
.hiw-eyebrow{color:#3765f8;margin:0 0 .5rem;}
.hiw-diagramlabel{margin-bottom:.25rem;}
.hiw-diagram{margin-bottom:2.5rem;}
.hiw-diagram img{width:100%;border:1px solid #e3e7ea;border-radius:12px;}
.hiw-band{background:#f5f7f9;border:1px solid #e3e7ea;border-radius:16px;padding:2.5rem;gap:1rem;margin-bottom:4.5rem;}
.hiw-innoplus{background:linear-gradient(115deg,#161b56 0%,#1b216b 70%,#283190 100%);border-radius:16px;padding:3rem;gap:.75rem;margin-bottom:4.5rem;}
.hiw-eyebrow-light{color:#a8ceff;margin:0;}
.hiw-h2-light h2.elementor-heading-title{color:#fff;font-size:clamp(1.5rem,1.1rem + 1.2vw,2rem);font-weight:700;}
.hiw-light p{color:#d7e0ff;max-width:64ch;line-height:1.7;margin:0;}
.hiw-btn-light a.elementor-button{background:#fff !important;color:#1b216b !important;}
.hiw-btn-light a.elementor-button:hover{background:#a8ceff !important;}
.hiw-innoplus .hiw-btn{margin-top:1rem;}
.hiw-contact{align-items:center;gap:.5rem;padding-top:1rem;border-top:1px solid #e3e7ea;}
@media (max-width:900px){
.hiw-cards{flex-direction:column;}
.hiw-row{flex-direction:column;}
.hiw-icons{flex-wrap:wrap;}
.doc-hero .hero-motif{display:none;}
}
